#import <UIKit/UIKit.h>
#import <objc/runtime.h>

static NSString *logPath = @"/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-tirh7h7z/opencode/probe/log.txt";

static void logLine(NSString *s) {
    NSFileHandle *fh = [NSFileHandle fileHandleForWritingAtPath:logPath];
    if (!fh) { [[NSFileManager defaultManager] createFileAtPath:logPath contents:nil attributes:nil]; fh = [NSFileHandle fileHandleForWritingAtPath:logPath]; }
    [fh seekToEndOfFile];
    [fh writeData:[[s stringByAppendingString:@"\n"] dataUsingEncoding:NSUTF8StringEncoding]];
    [fh closeFile];
}

static void collectTables(UIView *v, NSMutableArray *out) {
    if ([v isKindOfClass:[UITableView class]]) [out addObject:v];
    for (UIView *s in v.subviews) collectTables(s, out);
}

static void dumpLabels(UIView *v, NSMutableArray *out) {
    if ([v isKindOfClass:[UILabel class]] && ((UILabel *)v).text.length) [out addObject:((UILabel *)v).text];
    for (UIView *s in v.subviews) dumpLabels(s, out);
}

__attribute__((constructor)) static void probeInit(void) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 6 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
        logLine(@"probe start");
        for (UIScene *scene in [UIApplication sharedApplication].connectedScenes) {
            if (![scene isKindOfClass:[UIWindowScene class]]) continue;
            for (UIWindow *w in ((UIWindowScene *)scene).windows) {
                NSMutableArray *tables = [NSMutableArray array];
                collectTables(w, tables);
                logLine([NSString stringWithFormat:@"window %@ tables=%lu", NSStringFromClass([w class]), (unsigned long)tables.count]);
                for (UITableView *tv in tables) {
                    logLine([NSString stringWithFormat:@"table %@ rows=%ld", NSStringFromClass([tv class]), (long)[tv numberOfRowsInSection:0]]);
                    for (UITableViewCell *c in tv.visibleCells) {
                        NSMutableArray *labels = [NSMutableArray array];
                        dumpLabels(c, labels);
                        NSIndexPath *ip = [tv indexPathForCell:c];
                        id cd = nil;
                        @try { cd = [c valueForKey:@"cellData"]; } @catch (__unused NSException *e) {}
                        NSString *extra = @"";
                        @try {
                            id rs = [cd valueForKey:@"roomSummary"];
                            extra = [NSString stringWithFormat:@" roomId=%@ isDirect=%@ directUserId=%@ displayname=%@", [rs valueForKey:@"roomId"], [rs valueForKey:@"isDirect"], [rs valueForKey:@"directUserId"], [rs valueForKey:@"displayname"]];
                        } @catch (__unused NSException *e) { extra = @" (no roomSummary)"; }
                        logLine([NSString stringWithFormat:@"  row %ld.%ld %@ labels=%@%@", (long)ip.section, (long)ip.row, NSStringFromClass([c class]), labels, extra]);
                    }
                }
            }
        }
        logLine(@"probe end");
    });
}

