#import <UIKit/UIKit.h>
#import <objc/runtime.h>

static NSString *logPath = @"/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-tirh7h7z/opencode/probe/act-log.txt";

static void logLine(NSString *s) {
    if (![[NSFileManager defaultManager] fileExistsAtPath:logPath]) [[NSFileManager defaultManager] createFileAtPath:logPath contents:nil attributes:nil];
    NSFileHandle *fh = [NSFileHandle fileHandleForWritingAtPath:logPath];
    [fh seekToEndOfFile];
    [fh writeData:[[s stringByAppendingString:@"\n"] dataUsingEncoding:NSUTF8StringEncoding]];
    [fh closeFile];
}

static void collectTables(UIView *v, NSMutableArray *out) {
    if ([v isKindOfClass:[UITableView class]]) [out addObject:v];
    for (UIView *s in v.subviews) collectTables(s, out);
}

static UIView *ivarView(id obj, const char *name) {
    Ivar iv = class_getInstanceVariable([obj class], name);
    return iv ? object_getIvar(obj, iv) : nil;
}

__attribute__((constructor)) static void actInit(void) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 6 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
        UITableView *table = nil;
        for (UIScene *scene in [UIApplication sharedApplication].connectedScenes) {
            if (![scene isKindOfClass:[UIWindowScene class]]) continue;
            for (UIWindow *w in ((UIWindowScene *)scene).windows) {
                NSMutableArray *tables = [NSMutableArray array];
                collectTables(w, tables);
                if (tables.count && !table) table = tables.firstObject;
            }
        }
        if (!table) { logLine(@"no table"); return; }
        NSIndexPath *target = [NSIndexPath indexPathForRow:0 inSection:0];
        UITableViewCell *cell = [table cellForRowAtIndexPath:target];
        UIView *pres = ivarView(cell, "_presenceIndicatorView");
        logLine([NSString stringWithFormat:@"row0 presence hidden=%d alpha=%f", pres.hidden, pres.alpha]);
        UITableViewCell *other = [table cellForRowAtIndexPath:[NSIndexPath indexPathForRow:5 inSection:0]];
        UIView *pres2 = ivarView(other, "_presenceIndicatorView");
        logLine([NSString stringWithFormat:@"row5 presence hidden=%d alpha=%f", pres2.hidden, pres2.alpha]);
        if (pres.hidden || pres.alpha == 0) { logLine(@"row0 is not a DM, aborting"); return; }
        id delegate = table.delegate;
        if ([delegate respondsToSelector:@selector(tableView:didSelectRowAtIndexPath:)]) {
            [delegate tableView:table didSelectRowAtIndexPath:target];
            logLine(@"selected row0");
        } else {
            logLine(@"delegate missing method");
        }
    });
}

